using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
namespace InterviewForge.IntegrationTests;
public class MultiUserTests(ApiFactory factory) : IClassFixture<ApiFactory>
{
    private async Task<HttpClient> Member(string name)
    {var c=factory.CreateClient();c.DefaultRequestHeaders.Add("X-InterviewForge","1");(await c.PostAsJsonAsync("/api/auth/register",new{username="u"+Guid.NewGuid().ToString("N")[..20],name=name,email=Guid.NewGuid()+"@example.test",password="Test-only-member-pass-123",role="Admin"})).EnsureSuccessStatusCode();return c;}
    private async Task<HttpClient> Admin()
    {var c=factory.CreateClient();c.DefaultRequestHeaders.Add("X-InterviewForge","1");(await c.PostAsJsonAsync("/api/auth/login",new{username="admin",password="Test-only-admin-pass-123"})).EnsureSuccessStatusCode();return c;}
    private static async Task<JsonElement> Body(HttpResponseMessage r){r.EnsureSuccessStatusCode();return await r.Content.ReadFromJsonAsync<JsonElement>();}
    private static object Q(int topic=1,string text="Ownership boundary question?")=>new{topicId=topic,text,answer="Ownership answer",difficulty="Intermediate",tags=Array.Empty<string>()};
    private static object Algo(string name="Ownership algorithm")=>new{category="Tests",name,problemStatement="Problem",explanation="Explanation",approach="Approach",timeComplexity="O(n)",spaceComplexity="O(1)",implementation="code",example="example",interviewQuestions="question",commonMistakes="mistake"};
    [Fact] public async Task Anonymous_cannot_read_or_write_private_API()
    {using var c=factory.CreateClient();Assert.Equal(HttpStatusCode.Unauthorized,(await c.GetAsync("/api/questions")).StatusCode);c.DefaultRequestHeaders.Add("X-InterviewForge","1");Assert.Equal(HttpStatusCode.Unauthorized,(await c.PostAsJsonAsync("/api/questions",Q())).StatusCode);}
    [Fact] public async Task Members_only_edit_delete_own_shared_questions()
    {using var a=await Member("Alice");using var b=await Member("Bob");var q=await Body(await a.PostAsJsonAsync("/api/questions",Q()));var id=q.GetProperty("id").GetInt32();Assert.Equal("Alice",q.GetProperty("addedBy").GetString());Assert.True(q.GetProperty("canEdit").GetBoolean());var seen=await Body(await b.GetAsync($"/api/questions/{id}"));Assert.False(seen.GetProperty("canEdit").GetBoolean());Assert.Equal(HttpStatusCode.Forbidden,(await b.PutAsJsonAsync($"/api/questions/{id}",Q())).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await b.DeleteAsync($"/api/questions/{id}")).StatusCode);Assert.Equal(HttpStatusCode.OK,(await a.PutAsJsonAsync($"/api/questions/{id}",Q(text:"Updated ownership question?"))).StatusCode);Assert.Equal(HttpStatusCode.NoContent,(await a.DeleteAsync($"/api/questions/{id}")).StatusCode);}
    [Fact] public async Task Mine_filter_excludes_other_contributors()
    {using var a=await Member("Alice");using var b=await Member("Bob");var q=await Body(await a.PostAsJsonAsync("/api/questions",Q()));var mine=await Body(await b.GetAsync("/api/questions?filter=Mine"));Assert.DoesNotContain(mine.GetProperty("items").EnumerateArray(),x=>x.GetProperty("id").GetInt32()==q.GetProperty("id").GetInt32());}
    [Fact] public async Task Algorithms_are_shared_but_owner_admin_mutations_only()
    {using var a=await Member("Alice");using var b=await Member("Bob");using var admin=await Admin();var q=await Body(await a.PostAsJsonAsync("/api/algorithms",Algo()));var slug=q.GetProperty("slug").GetString();Assert.Equal("Alice",q.GetProperty("addedBy").GetString());Assert.Equal(HttpStatusCode.OK,(await b.GetAsync($"/api/algorithms/{slug}")).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await b.PutAsJsonAsync($"/api/algorithms/{slug}",Algo())).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await b.DeleteAsync($"/api/algorithms/{slug}")).StatusCode);Assert.Equal(HttpStatusCode.OK,(await a.PutAsJsonAsync($"/api/algorithms/{slug}",Algo())).StatusCode);Assert.Equal(HttpStatusCode.NoContent,(await admin.DeleteAsync($"/api/algorithms/{slug}")).StatusCode);}
    [Fact] public async Task Progress_notes_and_plans_are_isolated_and_admin_can_view_progress()
    {using var a=await Member("Alice");using var b=await Member("Bob");using var admin=await Admin();await a.PostAsJsonAsync("/api/questions/1/progress",new{status="Completed",isFavorite=true});await a.PutAsJsonAsync("/api/questions/1/note",new{body="Private Alice note"});var q=await Body(await b.GetAsync("/api/questions/1"));Assert.Equal("NotStarted",q.GetProperty("userState").GetProperty("status").GetString());Assert.Equal(JsonValueKind.Null,q.GetProperty("userState").GetProperty("note").ValueKind);var p=await Body(await a.PostAsJsonAsync("/api/plans",new{name="Alice plan",durationDays=5,questionsPerDay=10,studyMinutesPerDay=120}));Assert.Equal(HttpStatusCode.NotFound,(await b.GetAsync("/api/plans/"+p.GetProperty("id").GetInt32())).StatusCode);var me=await Body(await a.GetAsync("/api/auth/me"));var id=me.GetProperty("user").GetProperty("id").GetString();Assert.Equal(HttpStatusCode.Forbidden,(await b.GetAsync($"/api/admin/users/{id}/progress")).StatusCode);var report=await Body(await admin.GetAsync($"/api/admin/users/{id}/progress"));Assert.Contains(report.GetProperty("progress").EnumerateArray(),x=>x.GetProperty("questionId").GetInt32()==1&&x.GetProperty("status").GetString()=="Completed");}
    [Fact] public async Task Feedback_is_private_and_only_admin_reviews_without_implicit_content_changes()
    {using var a=await Member("Alice");using var b=await Member("Bob");using var admin=await Admin();var f=await Body(await a.PostAsJsonAsync("/api/feedback",new{kind="Question",contentId=1,message="Please correct this answer"}));var id=f.GetProperty("id").GetInt32();Assert.Equal("Pending",f.GetProperty("status").GetString());Assert.Equal(HttpStatusCode.Forbidden,(await b.PutAsJsonAsync($"/api/feedback/{id}/review",new{status="Accepted"})).StatusCode);var mine=await Body(await b.GetAsync("/api/feedback"));Assert.DoesNotContain(mine.EnumerateArray(),x=>x.GetProperty("id").GetInt32()==id);var review=await Body(await admin.PutAsJsonAsync($"/api/feedback/{id}/review",new{status="Accepted",adminResponse="Reviewed"}));Assert.Equal("Accepted",review.GetProperty("status").GetString());}
    [Fact] public async Task Signup_cannot_grant_admin_and_import_is_admin_only()
    {using var c=await Member("Member");var me=await Body(await c.GetAsync("/api/auth/me"));Assert.False(me.GetProperty("user").GetProperty("isAdmin").GetBoolean());Assert.Equal(HttpStatusCode.Forbidden,(await c.PostAsync("/api/admin/import",null)).StatusCode);}
    [Fact] public async Task Parent_delete_cannot_delete_another_users_child()
    {using var a=await Member("Alice");using var b=await Member("Bob");var s=await Body(await a.PostAsJsonAsync("/api/sections",new{name=Guid.NewGuid().ToString()}));var sid=s.GetProperty("id").GetInt32();var t=await Body(await a.PostAsJsonAsync("/api/topics",new{sectionId=sid,name="Owned topic"}));await b.PostAsJsonAsync("/api/questions",Q(t.GetProperty("id").GetInt32()));Assert.Equal(HttpStatusCode.Conflict,(await a.DeleteAsync($"/api/sections/{sid}")).StatusCode);Assert.Equal(HttpStatusCode.Conflict,(await a.DeleteAsync("/api/topics/"+t.GetProperty("id").GetInt32())).StatusCode);}
    [Fact] public async Task Admin_edits_and_deletions_survive_reimport()
    {using var a=await Member("Alice");using var admin=await Admin();var before=await Body(await admin.GetAsync("/api/questions/1"));var topic=before.GetProperty("topicId").GetInt32();Assert.Equal(HttpStatusCode.Forbidden,(await a.PutAsJsonAsync("/api/questions/1",Q(topic))).StatusCode);(await admin.PutAsJsonAsync("/api/questions/1",Q(topic,"Administrator corrected question?"))).EnsureSuccessStatusCode();await admin.PostAsync("/api/admin/import",null);var after=await Body(await admin.GetAsync("/api/questions/1"));Assert.Equal("Administrator corrected question?",after.GetProperty("text").GetString());var algos=await Body(await admin.GetAsync("/api/algorithms"));var slug=algos.EnumerateArray().First(x=>x.GetProperty("createdByUserId").ValueKind==JsonValueKind.Null).GetProperty("slug").GetString();Assert.Equal(HttpStatusCode.NoContent,(await admin.DeleteAsync($"/api/algorithms/{slug}")).StatusCode);await admin.PostAsync("/api/admin/import",null);Assert.Equal(HttpStatusCode.NotFound,(await admin.GetAsync($"/api/algorithms/{slug}")).StatusCode);}
    [Fact] public async Task Concurrent_first_progress_updates_succeed()
    {using var c=await Member("Concurrent");var q=await Body(await c.PostAsJsonAsync("/api/questions",Q()));var id=q.GetProperty("id").GetInt32();var responses=await Task.WhenAll(Enumerable.Range(0,4).Select(_=>c.PostAsJsonAsync($"/api/questions/{id}/progress",new{status="Completed"})));Assert.All(responses,r=>Assert.Equal(HttpStatusCode.OK,r.StatusCode));}
    [Fact] public async Task Signup_returns_signed_in_account_immediately()
    {using var c=factory.CreateClient();c.DefaultRequestHeaders.Add("X-InterviewForge","1");var body=await Body(await c.PostAsJsonAsync("/api/auth/register",new{username="u"+Guid.NewGuid().ToString("N")[..20],name="Immediate",email=Guid.NewGuid()+"@example.test",password="Test-only-member-pass-123"}));Assert.Equal("Immediate",body.GetProperty("user").GetProperty("displayName").GetString());}
    [Fact] public async Task Mutation_requires_CSRF_header()
    {using var c=await Member("Alice");c.DefaultRequestHeaders.Remove("X-InterviewForge");Assert.Equal(HttpStatusCode.Forbidden,(await c.PostAsJsonAsync("/api/questions",Q())).StatusCode);}
    [Fact] public async Task Signout_revokes_browser_access()
    {using var c=await Member("Alice");Assert.Equal(HttpStatusCode.NoContent,(await c.PostAsync("/api/auth/logout",null)).StatusCode);Assert.Equal(HttpStatusCode.Unauthorized,(await c.GetAsync("/api/progress")).StatusCode);}
    [Fact] public async Task Signup_rejects_duplicate_username_case_insensitively()
    {using var c=factory.CreateClient();c.DefaultRequestHeaders.Add("X-InterviewForge","1");var u="dup"+Guid.NewGuid().ToString("N")[..10];
     (await c.PostAsJsonAsync("/api/auth/register",new{username=u,name="A",email=Guid.NewGuid()+"@example.test",password="Test-only-member-pass-123"})).EnsureSuccessStatusCode();
     using var d=factory.CreateClient();d.DefaultRequestHeaders.Add("X-InterviewForge","1");
     var res=await d.PostAsJsonAsync("/api/auth/register",new{username=u.ToUpperInvariant(),name="B",email=Guid.NewGuid()+"@example.test",password="Test-only-member-pass-123"});
     Assert.Equal(System.Net.HttpStatusCode.Conflict,res.StatusCode);}
    [Fact] public async Task Login_uses_username_not_email()
    {using var c=factory.CreateClient();c.DefaultRequestHeaders.Add("X-InterviewForge","1");var u="log"+Guid.NewGuid().ToString("N")[..10];var mail=Guid.NewGuid()+"@example.test";
     (await c.PostAsJsonAsync("/api/auth/register",new{username=u,name="L",email=mail,password="Test-only-member-pass-123"})).EnsureSuccessStatusCode();
     using var d=factory.CreateClient();d.DefaultRequestHeaders.Add("X-InterviewForge","1");
     Assert.Equal(System.Net.HttpStatusCode.Unauthorized,(await d.PostAsJsonAsync("/api/auth/login",new{username=mail,password="Test-only-member-pass-123"})).StatusCode);
     var ok=await Body(await d.PostAsJsonAsync("/api/auth/login",new{username=u,password="Test-only-member-pass-123"}));
     Assert.Equal(u,ok.GetProperty("user").GetProperty("username").GetString());Assert.False(ok.GetProperty("user").GetProperty("isAdmin").GetBoolean());}
}
